export declare const styles = "\n  :host {\n    \n  --_level-0: var(--gha-level-0, #eff2f5);\n  --_accent: var(--gha-accent, #1f883d);\n  --_text: var(--gha-text, #1f2328);\n  --_muted: var(--gha-muted, #59636e);\n  --_border: var(--gha-border, #d1d9e0);\n\n    --_level-1: var(--gha-level-1, color-mix(in oklab, var(--_accent) 30%, var(--_level-0)));\n    --_level-2: var(--gha-level-2, color-mix(in oklab, var(--_accent) 55%, var(--_level-0)));\n    --_level-3: var(--gha-level-3, color-mix(in oklab, var(--_accent) 80%, var(--_level-0)));\n    --_level-4: var(--gha-level-4, var(--_accent));\n    --_gap: var(--gha-cell-gap, 3px);\n    --_radius: var(--gha-cell-radius, 2px);\n    --_cell-max: var(--gha-cell-max, 24px);\n    display: block;\n    container-type: inline-size;\n    color: var(--_text);\n    font: inherit;\n    line-height: 1.5;\n  }\n\n  :host([theme='dark']) {\n    \n  --_level-0: var(--gha-level-0, #151b23);\n  --_accent: var(--gha-accent, #39d353);\n  --_text: var(--gha-text, #f0f6fc);\n  --_muted: var(--gha-muted, #9198a1);\n  --_border: var(--gha-border, #3d444d);\n\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :host(:not([theme='light'])) {\n      \n  --_level-0: var(--gha-level-0, #151b23);\n  --_accent: var(--gha-accent, #39d353);\n  --_text: var(--gha-text, #f0f6fc);\n  --_muted: var(--gha-muted, #9198a1);\n  --_border: var(--gha-border, #3d444d);\n\n    }\n  }\n\n  :host([hidden]) {\n    display: none;\n  }\n\n  *,\n  *::before,\n  *::after {\n    box-sizing: border-box;\n  }\n\n  .root {\n    display: flex;\n    flex-direction: column;\n    gap: 20px;\n  }\n\n  .stats {\n    display: grid;\n    grid-template-columns: repeat(3, minmax(0, 1fr));\n    margin: 0;\n  }\n\n  .stat {\n    min-width: 0;\n    padding: 0 16px;\n  }\n\n  .stat:first-child {\n    padding-left: 0;\n  }\n\n  .stat + .stat {\n    border-left: 1px solid var(--_border);\n  }\n\n  dt {\n    font-size: 12px;\n    color: var(--_muted);\n  }\n\n  dd {\n    margin: 4px 0 0;\n    font-size: 24px;\n    font-weight: 600;\n    line-height: 1.25;\n    letter-spacing: -0.01em;\n    font-variant-numeric: tabular-nums;\n    overflow-wrap: anywhere;\n  }\n\n  .activity {\n    --columns: repeat(var(--weeks), minmax(0, var(--_cell-max)));\n    width: fit-content;\n    max-width: 100%;\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n  }\n\n  .canvas {\n    display: grid;\n    grid-template-columns: var(--columns);\n    column-gap: var(--_gap);\n    row-gap: 8px;\n  }\n\n  .months {\n    grid-column: 1 / -1;\n    display: grid;\n    grid-template-columns: subgrid;\n    font-size: 12px;\n    line-height: 1;\n    color: var(--_muted);\n  }\n\n  .months span {\n    grid-row: 1;\n    white-space: nowrap;\n  }\n\n  .months-half {\n    display: none;\n  }\n\n  .half {\n    grid-column: span var(--span);\n    display: grid;\n    grid-template-columns: subgrid;\n    row-gap: 8px;\n  }\n\n  .grid {\n    grid-column: 1 / -1;\n    display: grid;\n    grid-template-columns: subgrid;\n    grid-template-rows: repeat(7, auto);\n    grid-auto-flow: column;\n    row-gap: var(--_gap);\n  }\n\n  .cell {\n    display: block;\n    aspect-ratio: 1;\n    border-radius: var(--_radius);\n    background: var(--_level-0);\n  }\n\n  .cell[data-level='1'] {\n    background: var(--_level-1);\n  }\n\n  .cell[data-level='2'] {\n    background: var(--_level-2);\n  }\n\n  .cell[data-level='3'] {\n    background: var(--_level-3);\n  }\n\n  .cell[data-level='4'] {\n    background: var(--_level-4);\n  }\n\n  .pending .grid .cell {\n    opacity: 0;\n  }\n\n  .meta {\n    display: flex;\n    flex-wrap: wrap;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px 32px;\n  }\n\n  .caption {\n    margin: 0;\n    font-size: 13px;\n    color: var(--_muted);\n  }\n\n  .source {\n    white-space: nowrap;\n  }\n\n  .caption a {\n    color: var(--_text);\n    text-decoration: underline;\n    text-decoration-color: var(--_border);\n    text-underline-offset: 4px;\n  }\n\n  .caption a:hover {\n    text-decoration-color: currentColor;\n  }\n\n  .caption a:focus-visible {\n    outline: 2px solid var(--_accent);\n    outline-offset: 2px;\n    border-radius: 2px;\n  }\n\n  .legend {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin-left: auto;\n    font-size: 12px;\n    color: var(--_muted);\n  }\n\n  .swatches {\n    display: flex;\n    gap: var(--_gap);\n  }\n\n  .swatches .cell {\n    width: 11px;\n  }\n\n  @container (max-width: 639px) {\n    .canvas {\n      grid-template-columns: repeat(var(--split), minmax(0, var(--_cell-max)));\n      row-gap: 16px;\n    }\n\n    .months-full {\n      display: none;\n    }\n\n    .months-half {\n      display: grid;\n    }\n\n    .half {\n      grid-column: 1 / -1;\n    }\n  }\n\n  @container (max-width: 479px) {\n    .stats {\n      grid-template-columns: minmax(0, 1fr);\n      gap: 12px;\n    }\n\n    .stat,\n    .stat:first-child {\n      padding: 0;\n    }\n\n    .stat + .stat {\n      border-left: 0;\n      border-top: 1px solid var(--_border);\n      padding-top: 12px;\n    }\n  }\n";
